147	    @Transactional(rollbackFor = Exception.class)
148	    public Boolean handleNode(DispatchHandleParam handleParam, OperatorDTO operator) {
149	        Preconditions.checkArgument(handleParam.getTaskDispatchNodeId() != null ||
150	                !StringUtils.isEmpty(handleParam.getSalesSubOrderNo()));
151	
152	        if (handleParam.getTaskDispatchNodeId() == null) {
153	            return handleWithoutTask(handleParam, operator);
154	        }
155	        logger.info("TaskDispatchServiceImpl.handle param={},operator={}", JsonUtil.toJsonString(handleParam), operator);
156	        TaskDispatchNode dispatchNode = taskDispatchNodeDao.getById(handleParam.getTaskDispatchNodeId());
157	        if (dispatchNode == null) {
158	            throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, TASK_NONE_EXIST);
159	        }
160	        TaskDispatch taskDispatch = taskDispatchDao.getById(dispatchNode.getTaskDispatchId());
161	        if (taskDispatch == null) {
162	            throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, TASK_NONE_EXIST);
163	        }
164	        if (SourceTypeEnum.RETAIL.getType().equals(taskDispatch.getSourceType())
165	                && "".equals(taskDispatch.getProcessCode())) {
166	            XlsOrderInfoBo xlsOrderInfoBo = new XlsOrderInfoBo();
167	            BeanUtils.copyProperties(handleParam, xlsOrderInfoBo);
168	            handleParam.setTaskDispatchId(taskDispatch.getId());
169	            handleParam.setSalesSubOrderNo(taskDispatch.getBusinessId());
170	            completeTaskDispatchNode(taskDispatch, dispatchNode, handleParam, operator);
171	            materialCreateV2Service.createMaterialTaskWithDefaultParam(handleParam, operator, xlsOrderInfoBo);
172	            return true;
173	        }
174	
175	
176	        if (dispatchNode.getProcessStatus().intValue() == TaskDispatchNodeStatusEnum.COMPLETED.getValue()) {
177	            return true;
178	        }
179	        if (dispatchNode.getProcessStatus().intValue() == TaskDispatchNodeStatusEnum.UN_ACTIVE.getValue()) {
180	            // 完成前置任务
181	            completePreTask(taskDispatch, operator);
182	            // 激活当前任务
183	            materialActivateV2Service.doActivateTaskDispatch(taskDispatch);
184	            // 完成前置节点
185	            completePreTaskNode(taskDispatch, dispatchNode, operator);
186	        }
187	
188	        // 完成节点
189	        completeTaskDispatchNode(taskDispatch, dispatchNode, handleParam, operator);
190	        // 改完之后再查最新的数据
191	        TaskDispatchNode currentNewNode = taskDispatchNodeDao.getById(dispatchNode.getId());
192	        // 发im push消息
193	        messagePushClient.pushMessageWhenTaskDispatchNodeProcessChange(dispatchNode.getId(),
194	                TaskDispatchNodeStatusEnum.COMPLETED);
195	        if (handleParam.getNoticeRetainTime() != null) {
196	            // 发时间变更消息
197	            materialTaskProducer.publishTaskDispatchTimeChange(Lists.newArrayList(currentNewNode), TimeChangeType.APPOINTMENT_TIME);
198	        }
199	
200	        // 计算本任务的延期天数
201	        // 无配置的不计算延期天数
202	        if (StringUtils.isNotBlank(currentNewNode.getProcessCode())) {
203	            estimatedTimeV2Service.updateDelayDays(currentNewNode);
204	        }
205	
206	        // 变更单直接完成taskDispatch
207	        if (dispatchNode.getNodeType() >= TaskChangeTypeEnum.CHANGE.getValue()) {
208	            TaskDispatch updateDispatch = TaskDispatch.builder().id(taskDispatch.getId())
209	                    .processStatus(TaskDispatchStatusEnum.COMPLETED.getValue().byteValue())
210	                    .modifyBy(operator.getUcid()).modifyName(operator.getUsername()).build();
211	            taskDispatchDao.updateById(updateDispatch);
212	            return true;
213	        }
214	
215	        Integer nextNode = null;
216	        // 回退
217	        if (QualifiedEnum.UNQUALIFIED.getValue().equals(handleParam.getQualified())) {
218	            // 重启并激活第一个节点，不修改taskDispatch
219	            List<TaskDispatchNode> restartNodes = materialRestartV2Service.restartProcess(taskDispatch, dispatchNode);
220	            if (!CollectionUtils.isEmpty(restartNodes)) {
221	                nextNode = restartNodes.get(0).getNodeType();
222	                // 复尺驳回：推送通知给通知节点执行人
223	                messagePushClient.pushMessageWhenRecheckRejected(taskDispatch, dispatchNode, restartNodes);
224	            }
225	        } else {
226	            // 激活下一个节点
227	            nextNode = NodeTypeUtil.getNextNodeType(taskDispatch.getNodeTask(), dispatchNode.getNodeType());
228	            taskDispatchNodeDao.activateNextNode(taskDispatch.getId(), nextNode);
229	        }
230	        if (nextNode != null) {
231	            // 发消息
232	            List<TaskDispatchNode> nodeList = taskDispatchNodeDao.getByTaskIdAndNoteType(taskDispatch.getId(), nextNode);
233	            for (TaskDispatchNode taskDispatchNode : nodeList) {
234	                messagePushClient.pushMessageWhenTaskDispatchNodeProcessChange(taskDispatchNode.getId(), TaskDispatchNodeStatusEnum.UNCOMPLETED);
235	            }
236	        }
237	
238	        // 修改TaskDispatch表的currNode
239	        TaskDispatch updateDispatch = prepareHandleDispatch(nextNode, dispatchNode, operator);
240	        boolean result = taskDispatchDao.updateById(updateDispatch) > 0;
241	        TaskDispatch task = taskDispatchDao.getById(taskDispatch.getId());
242	
243	        // 通知供应链
244	        if (ModeEnum.isHome2_5_MODE(taskDispatch.getMode())
245	                || taskDispatch.getMode().equals(ModeEnum.HOME2_5.getValue())) {
246	            omsMessageSyncService.sendVssFinish(task, currentNewNode);
247	            omsMessageSyncService.sendVssNew(taskDispatch, nextNode, handleParam);
248	        } else {
249	            omsMessageSyncService.sendOmsMsg(taskDispatch, dispatchNode, nextNode);
250	        }
251	
252	        // 发node complete消息
253	        if (handleParam.getQualified() != null) {
254	            dispatchNode.setQualified(handleParam.getQualified());
255	        }
256	        materialTaskProducer.publishTaskNodeChange(taskDispatch, currentNewNode);
257	        // dispatch 变更消息
258	        materialTaskProducer.publishTaskDispatchChange(task);
259	
260	        // 给C端发消息
261	        if (nextNode == null) {
262	            materialCustomerProducer.publishMaterialCustomer(taskDispatch);
263	        }
264	        // 激活下一个taskDispatch
265	        if (TaskDispatchStatusEnum.COMPLETED.getValue().byteValue() == task.getProcessStatus()) {
266	            materialActivateV2Service.activateNextTaskDispatch(task);
267	        }
268	        logger.info("handleNode#afterHandler start:{}", currentNewNode);
269	        afterHandle(currentNewNode, task);
270	        return result;
271	    }
