273	    private void afterHandle(TaskDispatchNode currentNewNode, TaskDispatch taskDispatch) {
274	        if (Objects.isNull(currentNewNode)) {
275	            return;
276	        }
277	        if (ProcessStatusEnum.FINISHED.getValue().equals(taskDispatch.getProcessStatus().intValue())) {
278	            // 双写同步oms
279	            ServiceOrderOperateParam param = new ServiceOrderOperateParam();
280	            param.setBusinessId(taskDispatch.getId() + "");
281	            param.setOperation(SubOrderEventEnum.SIGN_FOR);
282	            scmManager.serviceOrderStatusChange(param);
283	        }
284	        if (TransactionSynchronizationManager.isActualTransactionActive()) {
285	            TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronizationAdapter() {
286	                @Override
287	                public void afterCommit() {
288	                    // 进展变更加入redis
289	                    CompletableFuture.runAsync(RunnableWrapper.of(() -> {
290	                        taskProgressTipService.addCache(taskDispatch.getProjectOrderId(),
291	                                taskDispatch.getMaterialCode().concat("#").concat(taskDispatch.getSupplierCode()), 3);
292	                    }));
293	                    // 依赖的任务考核时间变更
294	                    updateNodeEstime(currentNewNode);
295	                    // 计算激活时间
296	                    CompletableFutureUtils.supplyAsync(() -> {
297	                        materialCommonService.calculatePlanCompleteTimeByUpdate(taskDispatch);
298	                        return null;
299	                    }, ACTIVIE_EXECUTOR);
300	                }
301	            });
302	        } else {
303	            this.updateNodeEstime(currentNewNode);
304	            // 计算激活时间
305	            CompletableFutureUtils.supplyAsync(() -> {
306	                materialCommonService.calculatePlanCompleteTimeByUpdate(taskDispatch);
307	                return null;
308	            }, ACTIVIE_EXECUTOR);
309	        }
310	
311	        logger.info("afterHandle 复尺完成后需要主动推送报价变更任务 currentNewNode:{}, taskDispatch:{}", currentNewNode, taskDispatch);
312	        // 复尺完成后需要主动推送报价变更任务
313	        if (Objects.equals(taskDispatch.getTaskType(), TaskTypeEnum.RECHECK_SCALE.getValue()) && Objects.equals(taskDispatch.getMode(), ModeEnum.HOME2_5_MANPOWER.getValue())) {
314	            QueryTaskDispatchCondition condition = QueryTaskDispatchCondition.builder()
315	                    .projectOrderId(taskDispatch.getProjectOrderId())
316	                    .materialCode(taskDispatch.getMaterialCode())
317	                    .supplierCode(taskDispatch.getSupplierCode())
318	                    .taskTypeIn(Lists.newArrayList(TaskTypeEnum.DESIGN_REVIEW.getValue()))
319	                    .state(StateEnum.VALID.getValue())
320	                    .build();
321	            List<TaskDispatch> taskDispatchList = taskDispatchDao.list(condition);
322	            // 需要主动判断复尺是否完成，已完成需要主动推送sdm
323	            if (!CollectionUtils.isEmpty(taskDispatchList)) {
324	                for (TaskDispatch taskRecheck : taskDispatchList) {
325	                    if (Objects.equals(taskRecheck.getProcessStatus().intValue(), ProcessStatusEnum.FINISHED.getValue())) {
326	                        continue;
327	                    }
328	                    omsMessageSyncService.sendVssNew(taskRecheck, 60, null);
329	                }
330	            }
331	        }
332	
333	    }
