414	    @Override
415	    public Boolean handleTask(DispatchHandleParam handleParam, TaskDispatchParam taskDispatchParam, OperatorDTO operator) {
416	        if (Objects.isNull(taskDispatchParam) || Objects.isNull(taskDispatchParam.getProjectOrderId())){
417	            throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "项目ID不能为空");
418	        }
419	        if (Objects.isNull(handleParam)){
420	            handleParam = new DispatchHandleParam();
421	        }
422	        taskDispatchParam.setNotProcessStatus(ProcessStatusEnum.FINISHED.getValue());
423	        taskDispatchParam.setOrderByClause("task_dispatch_id asc,node_type asc");
424	        List<TaskDispatchDTO> taskDispatchDTOList = taskDispatchNodeDao.listTaskByCondition(taskDispatchParam);
425	        // 需要判断任务生成了，但是节点不存在的情况
426	        if(CollectionUtils.isEmpty(taskDispatchDTOList) && Boolean.TRUE.equals(handleParam.getNeedCreate())){
427	            List<TaskDispatch> taskDispatches = taskDispatchDao.listTaskDispatch(taskDispatchParam);
428	            if (CollectionUtils.isEmpty(taskDispatches)) {// 节点也不存在,任务不存在,
429	                return false;
430	            }
431	            TaskDispatch taskDispatch = taskDispatches.get(0);// 节点也不存在,任务存在,
432	            // 确定不是通过模板的，需要插入一条空的节点
433	            if (org.springframework.util.StringUtils.isEmpty(taskDispatch.getProcessCode())) {
434	                TaskDispatchNode taskDispatchNode = MaterialTaskBuildUtil.buildEmptyNode(taskDispatch,
435	                        NodeTypeEnum.getEnumByValue(taskDispatchParam.getNodeType()));
436	                taskDispatchNodeDao.insertSelective(taskDispatchNode);
437	                handleParam.setTaskDispatchNodeId(taskDispatchNode.getId());
438	            }
439	            if (Objects.nonNull(handleParam.getTaskDispatchNodeId())) {
440	                handleNode(handleParam, operator);
441	            }
442	        } else {
443	            for (TaskDispatchDTO taskDispatchDTO : taskDispatchDTOList) {
444	                handleParam.setTaskDispatchNodeId(taskDispatchDTO.getTaskDispatchNodeId());
445	                handleNode(handleParam,operator);
446	            }
447	        }
448	        return true;
449	    }
