458	    public Boolean handleWithoutTask(DispatchHandleParam dispatch, OperatorDTO operatorDTO) {
459	        XlsOrderInfoBo xlsOrderInfoBo = generateOrderInfo(dispatch.getSalesSubOrderNo());
460	        Long projectOrderId = xlsOrderInfoBo.getProjectOrderId();
461	        //校验是否已经存在任务实例
462	        List<TaskDispatch> taskDispatches =
463	                taskDispatchDao.listByCondition(TaskDispatch.builder()
464	                    .orderNo(xlsOrderInfoBo.getBusinessId())
465	                    .materialCode(xlsOrderInfoBo.getMaterialCode())
466	                    .supplierCode(xlsOrderInfoBo.getSupplierCode())
467	                    .mdmCode(xlsOrderInfoBo.getMdmCode())
468	                    .taskType(TaskTypeEnum.RECHECK_SCALE.getValue())
469	                    .mode(ModeEnum.HOME2_5.getValue()).build(), false);
470	        if(!CollectionUtils.isEmpty(taskDispatches)){
471	            logger.error("任务已生成,不能重复生成, param: {}", JsonUtils.obj2JsonStr(xlsOrderInfoBo));
472	            throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "任务已生成,不能重复生成");
473	        }
474	
475	        if(isTemplateExist(xlsOrderInfoBo)){
476	            //有配置 无实例
