558	    @Override
559	    public Boolean batchHandleNode(DispatchHandleParam handleParam, OperatorDTO operator) {
560	        long start = System.currentTimeMillis();
561	        if (CollectionUtils.isEmpty(handleParam.getTaskDispatchNodeIdList())) {
562	            return false;
563	        }
564	        List<Long> taskDispatchNodeIdList = handleParam.getTaskDispatchNodeIdList();
565	        List<TaskDispatchNode> taskDispatchNodes = taskDispatchNodeDao.listByIds(taskDispatchNodeIdList);
566	        Map<Long, TaskDispatchNode> nodeMap = taskDispatchNodes.stream()
567	                .collect(Collectors.toMap(TaskDispatchNode::getId, Function.identity(), (o1, o2) -> o1));
568	        // 使用CompletableFuture并行处理
569	        List<CompletableFuture<Void>> futures = new ArrayList<>();
570	
571	        for (Long taskDispatchNodeId : handleParam.getTaskDispatchNodeIdList()) {
572	            TaskDispatchNode taskDispatchNode = nodeMap.get(taskDispatchNodeId);
573	            if (Objects.isNull(taskDispatchNode)
574	                    || ProcessStatusEnum.FINISHED.getValue().equals(taskDispatchNode.getProcessStatus().intValue())) {
575	                logger.info("batchHandleNode node has finished:{}", taskDispatchNodeId);
576	                continue;
577	            }
578	            CompletableFuture<Void> future = CompletableFuture.runAsync(RunnableWrapper.of(() -> {
579	                DispatchHandleParam param = new DispatchHandleParam();
580	                param.setTaskDispatchNodeId(taskDispatchNodeId);
581	                param.setNoticeRetainTime(handleParam.getNoticeRetainTime());
582	                handleNode(param, operator);
583	            }), bactchHandleExecutorService);
584	
585	            futures.add(future);
586	        }
587	        // 等待所有任务完成
588	        CompletableFuture.allOf(futures.toArray(new CompletableFuture[0])).join();
589	        logger.info("End method batchHandleNode  耗时时间:{}", (System.currentTimeMillis() - start));
590	        return true;
591	    }
