695	    private void completePreTask(TaskDispatch taskDispatch, OperatorDTO operator) {
696	        // 任务已激活则返回
697	        if (taskDispatch.getProcessStatus().intValue() != TaskDispatchStatusEnum.UN_ACTIVE.getValue()) {
698	            return;
699	        }
700	        // 根据路由找前置任务的process_code
701	        List<NMaterialRoute> nMaterialRoutes = nMaterialRouteDao.queryList(NMaterialRouteCondition.builder().
702	                targetCode(taskDispatch.getProcessCode()).
703	                type(RouteTypeEnum.PROCESS.getValue()).
704	                state(com.ke.utopia.starlord.enumeration.StateEnum.VALID.getValue().byteValue())
705	                .build());
706	        if (CollectionUtils.isEmpty(nMaterialRoutes)) {
707	            return;
708	        }
709	        NMaterialRoute nMaterialRoute = nMaterialRoutes.get(0);
710	        // 无前置路由则返回
711	        if (Objects.isNull(nMaterialRoute.getSourceCode())) {
712	            return;
713	        }
714	        // 根据process_code,订单id,主材code,供应商code找生效的前置任务
715	        TaskDispatchExample preTaskDispatchExample = new TaskDispatchExample();
716	        TaskDispatchExample.Criteria taskDispatchCriteria = preTaskDispatchExample.createCriteria();
717	        taskDispatchCriteria.andStateEqualTo(com.ke.utopia.starlord.enumeration.StateEnum.VALID.getValue().byteValue())
718	                .andProcessCodeEqualTo(nMaterialRoute.getSourceCode())
719	                .andProjectOrderIdEqualTo(taskDispatch.getProjectOrderId())
720	                .andMaterialCodeEqualTo(taskDispatch.getMaterialCode())
721	                .andSupplierCodeEqualTo(taskDispatch.getSupplierCode());
722	        if (Objects.nonNull(taskDispatch.getOrderNo())) {
723	            taskDispatchCriteria.andOrderNoEqualTo(taskDispatch.getOrderNo());
724	        }
725	        List<TaskDispatch> preTaskDispatchList = taskDispatchDao.listByExample(preTaskDispatchExample);
726	        if (CollectionUtils.isEmpty(preTaskDispatchList)) {
727	            return;
728	        }
729	        TaskDispatch preTaskDispatch = preTaskDispatchList.get(0);
730	
731	        // 前置任务未激活则递归继续找
732	        if (TaskDispatchStatusEnum.UN_ACTIVE.getValue().byteValue() == preTaskDispatch.getProcessStatus()) {
733	            completePreTask(preTaskDispatch, operator);
734	        }
735	
736	
737	        // 顺次完成前置任务节点
738	        TaskDispatchNodeExample preTaskDispatchNodeExample = new TaskDispatchNodeExample();
739	        preTaskDispatchNodeExample.createCriteria().andTaskDispatchIdEqualTo(preTaskDispatch.getId())
740	                .andStateEqualTo(com.ke.utopia.starlord.enumeration.StateEnum.VALID.getValue().byteValue())
741	                .andProcessStatusNotEqualTo(TaskDispatchNodeStatusEnum.COMPLETED.getValue().byteValue());
742	        List<TaskDispatchNode> preDispatchNodeList = taskDispatchNodeDao.listByExample(preTaskDispatchNodeExample);
743	
744	        Map<Boolean, List<TaskDispatchNode>> partitioningByStartTime = preDispatchNodeList.stream()
745	                .collect(Collectors.partitioningBy(p -> Objects.equals(p.getStartTime().getTime(), CommonConstant.getInitDate().getTime())));
746	
747	        TaskDispatchNode updateTaskDispatchNode = TaskDispatchNode.builder()
748	                .processStatus(TaskDispatchNodeStatusEnum.COMPLETED.getValue().byteValue())
749	                .endTime(new Date())
750	                .submitTime(new Date())
751	                .remarks("上游系统已完成对应任务")
752	                .build();
753	        if (null != operator.getUcid()) {
754	            updateTaskDispatchNode.setSubmitName("自动完成");
755	            updateTaskDispatchNode.setSubmitBy(operator.getUcid() + "");
756	            updateTaskDispatchNode.setModifyBy(operator.getUcid() + "");
757	            updateTaskDispatchNode.setModifyName("自动完成");
758	        }
759	        // 批量更新TaskDispatchNode
760	        batchUpdateTaskDispatchNode(updateTaskDispatchNode, partitioningByStartTime);
761	
762	        // 发送前置节点变更消息
763	        if (!preDispatchNodeList.isEmpty()) {
764	            //设置完成态， 在完成时 才通知零售侧
765	            preDispatchNodeList.forEach(p -> p.setProcessStatus(TaskDispatchNodeStatusEnum.COMPLETED.getValue().byteValue()));
766	            materialTaskProducer.publishTaskNodeChange(Lists.newArrayList(preTaskDispatch), preDispatchNodeList);
767	        }
768	
769	        // 完成前置TaskDispatch
770	        TaskDispatch updatePreTaskDispatch = TaskDispatch.builder()
771	                .processStatus(TaskDispatchStatusEnum.COMPLETED.getValue().byteValue())
772	                .currentNodeType(1000).currentNodeTime(new Date())
773	                .modifyBy(operator.getUcid() + "").modifyName(operator.getUsername()).build();
774	        TaskDispatchExample preTaskDispatchUpdateExample = new TaskDispatchExample();
775	        preTaskDispatchUpdateExample.createCriteria().andIdEqualTo(preTaskDispatch.getId());
776	        taskDispatchDao.updateByExampleSelective(updatePreTaskDispatch, preTaskDispatchUpdateExample);
777	        // 发送前置任务变更消息
778	        materialTaskProducer.publishTaskDispatchChange(preTaskDispatch);
779	
780	
781	    }
782	
783	    private void batchUpdateTaskDispatchNode(TaskDispatchNode updateTaskDispatchNode, Map<Boolean, List<TaskDispatchNode>> partitioningByStartTime) {
784	        if (!CollectionUtils.isEmpty(partitioningByStartTime.get(false))) {
785	            List<Long> nodeIds = partitioningByStartTime.get(false).stream().map(TaskDispatchNode::getId).collect(Collectors.toList());
786	            TaskDispatchNodeExample taskDispatchNodeUpdateExample = new TaskDispatchNodeExample();
787	            taskDispatchNodeUpdateExample.createCriteria().andIdIn(nodeIds);
788	            taskDispatchNodeDao.updateByExampleSelective(updateTaskDispatchNode, taskDispatchNodeUpdateExample);
789	        }
790	        if (!CollectionUtils.isEmpty(partitioningByStartTime.get(true))) {
791	            updateTaskDispatchNode.setStartTime(updateTaskDispatchNode.getEndTime());
792	            List<Long> nodeIds = partitioningByStartTime.get(true).stream().map(TaskDispatchNode::getId).collect(Collectors.toList());
793	            TaskDispatchNodeExample taskDispatchNodeUpdateExample = new TaskDispatchNodeExample();
794	            taskDispatchNodeUpdateExample.createCriteria().andIdIn(nodeIds);
795	            taskDispatchNodeDao.updateByExampleSelective(updateTaskDispatchNode, taskDispatchNodeUpdateExample);
796	        }
797	    }
798	}
