16	import java.util.Collections;
17	import java.util.List;
18	
19	@Slf4j
20	@Repository
21	public class MaterialNotifyTaskAutomationDaoImpl implements MaterialNotifyTaskAutomationDao {
22	
23	    /**
24	     * 单条 SQL 允许的最大维度数。维度过多时 IN 列表过大（1459 维度 → 2918 绑定参数）会被数据库/代理层拒绝或执行计划劣化，按批拆分查询。
25	     */
26	    private static final int MAX_DIMENSIONS_PER_QUERY = 500;
27	
28	    private final Logger logger = LoggerFactory.getLogger(MaterialNotifyTaskAutomationDaoImpl.class);
29	
30	    @Resource
31	    private MaterialNotifyTaskAutomationMapper materialNotifyTaskAutomationMapper;
32	
33	    @Override
34	    public Long insertSelective(MaterialNotifyTaskAutomation record) {
35	        materialNotifyTaskAutomationMapper.insertSelective(record);
36	        return record.getId();
37	    }
38	
39	    @Override
40	    public int batchInsert(List<MaterialNotifyTaskAutomation> records) {
41	        return materialNotifyTaskAutomationMapper.batchInsert(records);
42	    }
43	
44	    @Override
45	    public MaterialNotifyTaskAutomation selectById(Long id) {
46	        return materialNotifyTaskAutomationMapper.selectByPrimaryKey(id);
47	    }
48	
49	    @Override
50	    public void updateById(MaterialNotifyTaskAutomation record) {
51	        materialNotifyTaskAutomationMapper.updateByPrimaryKeySelective(record);
52	    }
53	
54	    @Override
55	    public List<MaterialNotifyTaskAutomation> queryLatestNotifyUnDoneByDimension(MaterialNotifyTaskAutomationQueryCondition condition) {
56	        if (condition == null || CollectionUtils.isEmpty(condition.getDimensions())) {
57	            return Collections.emptyList();
58	        }
59	        logger.info("queryLatestNotifyUnDoneByDimension condition={}", condition);
60	        List<MaterialNotifyTaskAutomationQueryCondition.Dimension> dimensions = condition.getDimensions();
61	        if (dimensions.size() <= MAX_DIMENSIONS_PER_QUERY) {
62	            return materialNotifyTaskAutomationMapper.queryLatestNotifyUnDoneByDimension(condition);
63	        }
64	        // 维度过多：按批查询后合并，避免单条 SQL 的 (project_order_id, material_code) IN 列表过大
65	        List<MaterialNotifyTaskAutomation> result = new ArrayList<>();
66	        for (List<MaterialNotifyTaskAutomationQueryCondition.Dimension> partition : Lists.partition(dimensions, MAX_DIMENSIONS_PER_QUERY)) {
67	            MaterialNotifyTaskAutomationQueryCondition chunkCondition = MaterialNotifyTaskAutomationQueryCondition.builder()
68	                    .dimensions(partition)
69	                    .taskType(condition.getTaskType())
70	                    .notifyExecuteType(condition.getNotifyExecuteType())
71	                    .build();
72	            List<MaterialNotifyTaskAutomation> records = materialNotifyTaskAutomationMapper
73	                    .queryLatestNotifyUnDoneByDimension(chunkCondition);
74	            logger.info("queryLatestNotifyUnDoneByDimension chunkCondition={} 查询结果={}", chunkCondition, records);
75	            if (!CollectionUtils.isEmpty(records)) {
76	                result.addAll(records);
77	            }
78	        }
79	        return result;
80	    }
81	
82	    @Override
83	    public List<MaterialNotifyTaskAutomation> selectAutoNotifyCandidates(MaterialNotifyTaskAutomationQueryCondition condition) {
84	        if (condition == null) {
85	            return Collections.emptyList();
86	        }
87	        return materialNotifyTaskAutomationMapper.selectAutoNotifyCandidates(condition);
88	    }
89	
90	
91	    @Override
92	    public List<MaterialNotifyTaskAutomation> selectByEntity(MaterialNotifyTaskAutomation record) {
93	        if (record == null) {
94	            return Collections.emptyList();
95	        }
96	        return materialNotifyTaskAutomationMapper.selectByEntity(record);
97	    }
98	}
