32	
33	    @Override
34	    public void receiveTaskResult(List<NotifyTaskResultParam> params) {
35	        for (NotifyTaskResultParam param : params) {
36	            if (apolloConfig.getReceiveRecognizeResultProjectIdMapping().containsKey(String.valueOf(param.getProjectOrderId()))) {
37	                param.setProjectOrderId(Long.valueOf(apolloConfig.getReceiveRecognizeResultProjectIdMapping().get(String.valueOf(param.getProjectOrderId()))));
38	                log.info("receiveTaskResult projectOrderId mapping, projectOrderId:{}, newProjectOrderId:{}", param.getProjectOrderId(), apolloConfig.getReceiveRecognizeResultProjectIdMapping().get(String.valueOf(param.getProjectOrderId())));
39	            }
40	            List<MaterialNotifyTaskAutomation> taskAutomations = materialNotifyTaskAutomationDao
41	                    .selectByEntity(MaterialNotifyTaskAutomation.builder().projectOrderId(param.getProjectOrderId())
42	                            .materialCode(param.getMaterialCode()).taskType(param.getTaskType()).build());
43	            MaterialNotifyTaskAutomation record = buildRecord(param);
44	            if (CollectionUtils.isEmpty(taskAutomations)) {
45	                materialNotifyTaskAutomationDao.insertSelective(record);
46	                log.info("receiveTaskResult insert, projectOrderId:{}, materialCode:{}, taskType:{}", param.getProjectOrderId(), param.getMaterialCode(), param.getTaskType());
47	            } else {
48	                MaterialNotifyTaskAutomation taskAutomation = taskAutomations.get(0);
49	                log.info("receiveTaskResult update, projectOrderId:{}, materialCode:{}, taskType:{}", param.getProjectOrderId(), param.getMaterialCode(), param.getTaskType());
50	//                if (!Objects.equals(taskAutomation.getNotifyExecuteType(), NotifyExecuteTypeEnum.NOT_EXECUTE.getValue())) {
51	//                    log.info("receiveTaskResult 任务已执行，不再接收识别结果，projectOrderId:{}, materialCode:{}, taskType:{}", param.getProjectOrderId(), param.getMaterialCode(), param.getTaskType());
52	//                    continue;
53	//                }
54	                record.setId(taskAutomation.getId());
55	                materialNotifyTaskAutomationDao.updateById(record);
56	            }
57	        }
58	    }
59	
60	    /**
61	     * 构建落库记录
62	     */
63	    private MaterialNotifyTaskAutomation buildRecord(NotifyTaskResultParam param) {
64	        return MaterialNotifyTaskAutomation.builder().projectOrderId(param.getProjectOrderId())
65	                .materialCode(param.getMaterialCode()).taskType(param.getTaskType()).receiveTime(new Date())
66	                .recognizeTime(param.getRecognizeTime()).recommendVisitTime(param.getRecommendVisitTime())
67	                .judgeResult(param.getJudgeResult().byteValue()).judgeRemark(param.getJudgeRemark())
68	                .images(buildImages(param)).build();
69	    }
70	
71	    /**
72	     * images 逗号分隔拼接；最多取前 MAX_IMAGE_COUNT 张，超出部分丢弃（通知页面九宫格上限）
73	     */
74	    private String buildImages(NotifyTaskResultParam param) {
75	        if (CollectionUtils.isEmpty(param.getImages())) {
76	            return "";
77	        }
78	        List<String> images = param.getImages();
79	        if (images.size() > MAX_IMAGE_COUNT) {
80	            log.info("receiveTaskResult images over limit, size:{}, keep:{}, projectOrderId:{}, materialCode:{}, taskType:{}",
81	                    images.size(), MAX_IMAGE_COUNT, param.getProjectOrderId(), param.getMaterialCode(), param.getTaskType());
82	            images = images.subList(0, MAX_IMAGE_COUNT);
83	        }
84	        return String.join(",", images);
85	    }
86	}

