164	    /**
165	     * 通知复尺查询公共方案：查 node → 重启去重 → automation 判定 → 归组（可通知/延期预警）→ 延期≤3天过滤。
166	     * 不含排序、地址、项目分组（各调用方按需处理）；judge=4（现场已完成，纯提醒，仅push）不进入结果。
167	     *
168	     * @param executorId 工长 ucid
169	     * @param param      查询参数，可空（空视为默认 taskType=3、无 projectOrderId 过滤）
170	     */
171	    private NotifyTaskSplitResult queryNotifyTaskSplit(String executorId, NotifyTaskQueryParam param) {
172	        if (StringUtils.isEmpty(executorId)) {
173	            throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "工长不能为空");
174	        }
175	        Integer taskType = param == null || param.getTaskType() == null ? DEFAULT_TASK_TYPE : param.getTaskType();
176	        logger.info("queryNotifyTaskSplit executorId={}, taskType={}, param={}", executorId, taskType, param);
177	        // 获取主材任务
178	        TaskDispatchParam taskDispatchParam = new TaskDispatchParam();
179	        taskDispatchParam.setExecutorId(executorId);
180	        taskDispatchParam.setTaskType(taskType);
181	        taskDispatchParam.setNodeType(NOTIFY_NODE_TYPE);
182	        taskDispatchParam.setProcessStatus(ProcessStatusEnum.UNFINISHED.getValue());
183	        if (param != null && param.getProjectOrderId() != null) {
184	            taskDispatchParam.setProjectOrderId(param.getProjectOrderId());
185	        }
186	        List<TaskDispatchDTO> taskList = taskDispatchNodeDao.listTaskByCondition(taskDispatchParam);
187	        if (CollectionUtils.isEmpty(taskList)) {
188	            return new NotifyTaskSplitResult(new ArrayList<>(), new ArrayList<>(), Collections.emptyMap());
189	        }
190	
191	        // 获取订单信息
192	        Set<Long> projectOrderIds = new HashSet<>();
193	        taskList.forEach(task -> projectOrderIds.add(task.getProjectOrderId()));
194	        Map<Long, ProjectOrderDetailBO> projectOrderMap = fetchProjectOrders(projectOrderIds);
195	
196	        long start = System.currentTimeMillis();
197	        // 获取推荐结果：按 (project_order_id, material_code, task_type)
198	        Map<String, MaterialNotifyTaskAutomation> notifyTaskAutomationMap = queryLatestNotifyUnDoneByDimension(taskList,
199	                taskType);
200	        long end = System.currentTimeMillis();
201	        log.info("queryLatestNotifyUnDoneByDimension cost: {}", end - start);
202	        List<NotifyTaskDetailVO> notifyTasks = new ArrayList<>();
203	        List<NotifyTaskDetailVO> delayTasks = new ArrayList<>();
204	        for (TaskDispatchDTO task : taskList) {
205	            // 校验开关
206	            ProjectOrderDetailBO order = projectOrderMap.get(task.getProjectOrderId());
207	            String gbCode = order == null ? null : order.getGbCode();
208	            String departmentCode = resolveDepartmentCode(order);
209	            if (!notifyAutomationConfig.isFeatureOpen(gbCode, executorId, departmentCode)) {
210	                logger.info("feature is not open for task: {}, gbCode: {}, executorId: {}, departmentCode: {}", task, gbCode, executorId, departmentCode);
211	                continue;
212	            }
213	            MaterialNotifyTaskAutomation materialNotifyTaskAutomation = notifyTaskAutomationMap
214	                    .get(dimensionKey(task.getProjectOrderId(), task.getMaterialCode()));
215	            Integer judgeResult = materialNotifyTaskAutomation == null || materialNotifyTaskAutomation.getJudgeResult() == null
216	                    ? NotifyJudgeResultEnum.CANNOT_JUDGE.getValue()
217	                    : materialNotifyTaskAutomation.getJudgeResult().intValue();
218	            logger.info("task={}, judgeResult={}", task, judgeResult);
219	            // judge=1 可通知；judge=2/3/4无automation记录 归延期预警；
220	            if (NotifyJudgeResultEnum.CAN_NOTIFY.getValue().equals(judgeResult)) {
221	                NotifyTaskDetailVO vo = buildDetail(task, materialNotifyTaskAutomation, projectOrderMap);
222	                notifyTasks.add(vo);
223	            } else {
224	                LocalDate cutoffDate = LocalDate.now().plusDays(DELAY_FILTER_WINDOW_DAYS);
225	                if (task.getEstimatedTime() != null && !task.getEstimatedTime().toInstant()
226	                        .atZone(ZoneId.systemDefault())
227	                        .toLocalDate()
228	                        .isAfter(cutoffDate)) {
229	                    NotifyTaskDetailVO vo = buildDetail(task, null, projectOrderMap);
230	                    if (materialNotifyTaskAutomation != null
231	                            && materialNotifyTaskAutomation.getJudgeResult().equals(NotifyJudgeResultEnum.CANNOT_NOTIFY.getValue().byteValue())) {
232	                        vo.setJudgeReason(materialNotifyTaskAutomation.getJudgeRemark());
233	                        vo.setJudgeResult(NotifyJudgeResultEnum.CANNOT_NOTIFY.getValue());
234	                        vo.setImages(splitImages(materialNotifyTaskAutomation.getImages()));
235	                    }
236	                    delayTasks.add(vo);
237	                }
238	            }
239	        }
240	        return new NotifyTaskSplitResult(notifyTasks, delayTasks, projectOrderMap);
241	    }
