243	    private boolean isInNotifyWindow() {
244	        if (apolloConfig.getMaterialNotifyTimeWindowEnabled()) {
245	            return true;
246	        }
247	        LocalTime now = LocalTime.now();
248	        for (String window : NOTIFY_WINDOWS) {
249	            String[] range = window.split("-");
250	            LocalTime start = LocalTime.parse(range[0]);
251	            LocalTime end = LocalTime.parse(range[1]);
252	            if (!now.isBefore(start) && !now.isAfter(end)) {   // 含端点
253	                return true;
254	            }
255	        }
256	        return false;
257	    }
