333	    private NotifyTaskDetailVO buildDetail(TaskDispatchDTO task, MaterialNotifyTaskAutomation auto, Map<Long, ProjectOrderDetailBO> projectOrderMap) {
334	        NotifyTaskDetailVO vo = new NotifyTaskDetailVO();
335	        vo.setProjectOrderId(String.valueOf(task.getProjectOrderId()));
336	        if (projectOrderMap.containsKey(task.getProjectOrderId())) {
337	            vo.setProjectAddress(projectOrderMap.get(task.getProjectOrderId()).getAddress());
338	        }
339	        vo.setTaskDispatchNodeId(task.getTaskDispatchNodeId());
340	        vo.setTaskDispatchId(task.getTaskDispatchId());
341	        vo.setBusinessId(task.getBusinessId());
342	        vo.setMaterialCode(task.getMaterialCode());
343	        vo.setMaterialName(task.getMaterialName());
344	        vo.setSupplierName(task.getSupplierName());
345	        vo.setTaskType(task.getTaskType());
346	        vo.setNodeType(task.getNodeType());
347	        vo.setTaskNodeName(NodeTypeEnum.getAliasName(task.getNodeType(), TaskTypeEnum.getNameByValue(task.getTaskType())));
348	        vo.setEstimatedTime(task.getEstimatedTime());
349	        // 期望上门时间/图片优先取 node，空则取 automation（通知结果表）兜底
350	        if (auto != null) {
351	            vo.setRecommendVisitTime(auto.getRecommendVisitTime());
352	            vo.setJudgeResult(auto.getJudgeResult().intValue());
353	            vo.setJudgeReason(auto.getJudgeRemark());
354	            vo.setImages(splitImages(auto.getImages()));
355	        }
356	        // Node 数据优先，有值才覆盖 Automation Node时间小于2000年也不能用
357	        Calendar calendar = Calendar.getInstance();
358	        calendar.setTime(task.getNoticeRetainTime());
359	        if (calendar.get(Calendar.YEAR) >= 2010) {
360	            vo.setRecommendVisitTime(task.getNoticeRetainTime());
361	        }
362	        if (!StringUtils.isEmpty(task.getImages())) {
363	            vo.setImages(splitImages(task.getImages()));
364	        }
365	        return vo;
366	    }
