387	    /**
388	     * 按项目聚合分组；地址在分组上（任务内不再重复）
389	     */
390	    private List<NotifyTaskProjectGroupVO> groupByProject(List<NotifyTaskDetailVO> tasks,
391	                                                          Map<Long, ProjectOrderDetailBO> projectOrderMap) {
392	        Map<String, List<NotifyTaskDetailVO>> grouped = tasks.stream()
393	                .collect(Collectors.groupingBy(NotifyTaskDetailVO::getProjectOrderId, LinkedHashMap::new, Collectors.toList()));
394	        List<NotifyTaskProjectGroupVO> result = new ArrayList<>();
395	        grouped.forEach((projectId, taskList) -> {
396	            // 排序
397	            taskList.sort(Comparator
398	                    .comparing(NotifyTaskDetailVO::getMaterialCode, Comparator.nullsLast(String::compareTo))
399	                    .thenComparing(NotifyTaskDetailVO::getEstimatedTime, Comparator.nullsLast(Date::compareTo)));
400	            // 赋值订单信息
401	            NotifyTaskProjectGroupVO group = NotifyTaskProjectGroupVO.builder()
402	                    .projectOrderId(projectId)
403	                    .tasks(taskList)
404	                    .build();
405	            ProjectOrderDetailBO order = projectOrderMap.get(Long.valueOf(projectId));
406	            if (order != null) {
407	                group.setProjectAddress(order.getAddress());   // 与复尺列表 UI 一致（houseDetail.address）
408	            }
409	            result.add(group);
410	        });
411	        return result;
412	    }
