414	    @Override
415	    public NotifyTaskBatchHandleResultVO batchHandleNotifyTasks(NotifyBatchHandleParam param) {
416	        if (CollectionUtils.isEmpty(param.getTaskDispatchNodeItems())) {
417	            return NotifyTaskBatchHandleResultVO.builder().successCount(0).successList(Collections.emptyList()).failList(Collections.emptyList()).build();
418	        }
419	        logger.info("batchHandleNotifyTasks param: {}", param);
420	        Map<Long, NotifyNodeHandleItem> itemMap = param.getTaskDispatchNodeItems().stream()
421	                .collect(Collectors.toMap(NotifyNodeHandleItem::getTaskDispatchNodeId, Function.identity(), (o1, o2) -> o1));
422	        List<Long> nodeIdList = param.getTaskDispatchNodeItems().stream()
423	                .map(NotifyNodeHandleItem::getTaskDispatchNodeId)
424	                .collect(Collectors.toList());
425	
426	        // 节点
427	        List<TaskDispatchNode> nodes = taskDispatchNodeDao.listByIds(nodeIdList);
428	        Map<Long, TaskDispatchNode> nodeMap = nodes.stream()
429	                .collect(Collectors.toMap(TaskDispatchNode::getId, Function.identity(), (o1, o2) -> o1));
430	        Set<Long> dispatchIds = nodes.stream()
431	                .map(TaskDispatchNode::getTaskDispatchId)
432	                .collect(Collectors.toSet());
433	        // task
434	        List<TaskDispatch> taskDispatches = taskDispatchDao.listByIds(Lists.newArrayList(dispatchIds));
435	        Map<Long, TaskDispatch> dispatchMap = taskDispatches.stream()
436	                .collect(Collectors.toMap(TaskDispatch::getId, Function.identity(), (o1, o2) -> o1));
437	
438	        // 获取推荐
439	        Map<String, MaterialNotifyTaskAutomation> autoMap = queryLatestNotifyUnDoneByDimension2(taskDispatches, DEFAULT_TASK_TYPE);
440	
441	        List<Long> successNodeIds = new ArrayList<>();
442	        List<Long> failedNodeIds = new ArrayList<>();
443	        // 操作员
444	        IOperator operator = OperatorContextHandler.getContext().getOperator();
445	        OperatorDTO operatorDTO = new OperatorDTO();
446	        operatorDTO.setUcid(String.valueOf(operator.getUcid()));
447	        operatorDTO.setUsername(operator.getUsername() + "（一键通知复尺）");
448	
449	        for (TaskDispatchNode node : nodes) {
450	            if (node.getTaskDispatchId() != null
451	                    && ProcessStatusEnum.FINISHED.getValue().equals(node.getProcessStatus().intValue())) {
452	                log.info("batchHandleNotifyTasks skip completed node: {}", node.getId());
453	                continue;
454	            }
455	            try {
456	                MaterialNotifyTaskAutomation auto = autoMap.get(dimensionKey(
457	                        node.getProjectOrderId(),
458	                        dispatchMap.get(node.getTaskDispatchId()).getMaterialCode()));
459	                DispatchHandleParam handleParam = new DispatchHandleParam();
460	                handleParam.setTaskDispatchNodeId(node.getId());
461	                // 图片必须大于等于3张
462	                if (itemMap.get(node.getId()).getImages().size() < 3) {
463	                    logger.warn("batchHandleNotifyTasks skip node {} due to images size < 3", node.getId());
464	                    failedNodeIds.add(node.getId());
465	                    continue;
466	                }
467	                // 设置图片和上门时间
468	                handleParam.setImages(itemMap.get(node.getId()).getImages());
469	                handleParam.setQualified(itemMap.get(node.getId()).getQualified());
470	                handleParam.setRemarks(itemMap.get(node.getId()).getRemarks());
471	                handleParam.setNoticeRetainTime(itemMap.get(node.getId()).getNoticeRetainTime());
472	                materialHandleV2Service.handleNode(handleParam, operatorDTO);
473	
474	                Integer adoptionType = classifyAdoption(auto, new HashSet<>(handleParam.getImages()), handleParam.getNoticeRetainTime());
475	                MaterialNotifyTaskAutomation update = MaterialNotifyTaskAutomation.builder()
476	                        .id(auto.getId())
477	                        .notifyExecuteType(NotifyExecuteTypeEnum.ONE_KEY_NOTIFY.getValue())
478	                        .aiAdoptionType(adoptionType == null ? 0 : adoptionType.byteValue())
479	                        .build();
480	
481	                materialNotifyTaskAutomationDao.updateById(update);
482	                successNodeIds.add(node.getId());
483	            } catch (Exception e) {
484	                failedNodeIds.add(node.getId());
485	                log.error("batchHandleNotifyTasks error: {}", node.getId(), e);
486	            }
487	        }
488	        // 所有节点 ID 列表以及项目 ID 集合
489	        List<Long> allNodeIds = new ArrayList<>(
490	                successNodeIds.size() + failedNodeIds.size());
491	
492	        allNodeIds.addAll(successNodeIds);
493	        allNodeIds.addAll(failedNodeIds);
494	
495	        Set<Long> projectOrderIds = allNodeIds.stream()
496	                .map(nodeMap::get)
497	                .filter(Objects::nonNull)
498	                .map(TaskDispatchNode::getProjectOrderId)
499	                .filter(Objects::nonNull)
500	                .collect(Collectors.toSet());
501	        // 项目订单信息
502	        Map<Long, ProjectOrderDetailBO> projectOrderMap =
