639	    /**
640	     * 自动执行通知任务：扫描 automation 表「昨日识别 + 可通知(judge=1) + 未执行(notify_execute_type=0)」候选，
641	     * 维度反查待通知节点（taskType=3 / nodeType=20 / processStatus=2）后，逐件经 autoNotify 开关校验，
642	     * 复用 handleNode 全链路完成通知（images/时间取自 automation 行）。受 notification.remeasure.automation.autoNotify 管控。
643	     */
644	    @Override
645	    public NotifyTaskAutoExecuteResultVO autoExecuteNotifyTasks() {
646	        MaterialNotifyTaskAutomation condition = MaterialNotifyTaskAutomation.builder()
647	                .judgeResult(NotifyJudgeResultEnum.CAN_NOTIFY.getValue().byteValue())
648	                .taskType(DEFAULT_TASK_TYPE)
649	                .build();
650	        List<MaterialNotifyTaskAutomation> candidates = materialNotifyTaskAutomationDao.selectByEntity(condition);
651	        logger.info("autoExecuteNotifyTasks candidates count: {}", candidates.size());
652	        if (CollectionUtils.isEmpty(candidates)) {
653	            return NotifyTaskAutoExecuteResultVO.builder()
654	                    .candidateCount(0).executedCount(0).build();
655	        }
656	
657	        // 2. 维度反查待通知节点（taskType=3 / nodeType=20 / processStatus=2 / 无 executor 即系统级扫描）
658	        List<Long> projectOrderIdList = candidates.stream()
659	                .map(MaterialNotifyTaskAutomation::getProjectOrderId)
660	                .distinct().collect(Collectors.toList());
661	        List<String> materialCodeList = candidates.stream()
662	                .map(MaterialNotifyTaskAutomation::getMaterialCode)
663	                .filter(Objects::nonNull).distinct().collect(Collectors.toList());
664	        TaskDispatchParam nodeParam = new TaskDispatchParam();
665	        nodeParam.setProjectOrderIdList(projectOrderIdList);
666	        nodeParam.setMaterialCodeList(materialCodeList);
667	        nodeParam.setTaskTypeList(Collections.singletonList(DEFAULT_TASK_TYPE));
668	        nodeParam.setNodeTypeList(Collections.singletonList(NOTIFY_NODE_TYPE));
669	        nodeParam.setProcessStatus(ProcessStatusEnum.UNFINISHED.getValue());
670	        List<TaskDispatchDTO> nodeList = taskDispatchNodeDao.listTaskByCondition(nodeParam);
671	        logger.info("autoExecuteNotifyTasks nodeList count: {}", nodeList.size());
672	
673	        // listTaskByCondition 的 projectOrderIdList / materialCodeList 是独立 IN（AND 语义），
674	        // 会产生 projList × matList 的超集节点；按候选维度精确收敛，避免无关组合进入映射
675	        Map<String, MaterialNotifyTaskAutomation> candidateMap = candidates.stream()
676	                .collect(Collectors.toMap(c -> dimensionKey(c.getProjectOrderId(), c.getMaterialCode()),
677	                        c -> c, (existing, replacement) -> existing));
678	        nodeList = nodeList.stream()
679	                .filter(n -> candidateMap.containsKey(dimensionKey(n.getProjectOrderId(), n.getMaterialCode())))
680	                .collect(Collectors.toList());
681	        Map<String, TaskDispatchDTO> nodeMap = new LinkedHashMap<>();
682	        for (TaskDispatchDTO n : nodeList) {
683	            nodeMap.put(dimensionKey(n.getProjectOrderId(), n.getMaterialCode()), n);
684	        }
685	
686	
687	        OperatorDTO operatorDTO = new OperatorDTO();
688	        operatorDTO.setUsername("系统自动通知复尺");
689	
690	        List<NotifyTaskDetailVO> executedNodes = new ArrayList<>();
691	        Set<Long> nodeProjectIds = new HashSet<>();
692	        nodeList.forEach(n -> nodeProjectIds.add(n.getProjectOrderId()));
693	        Map<Long, ProjectOrderDetailBO> projectOrderMap = fetchProjectOrders(nodeProjectIds);
694	        Integer successCount = 0;
695	        for (TaskDispatchDTO node : nodeList) {
696	            ProjectOrderDetailBO order = projectOrderMap.get(node.getProjectOrderId());
697	            MaterialNotifyTaskAutomation materialNotifyTaskAutomation = candidateMap.get(dimensionKey(node.getProjectOrderId(), node.getMaterialCode()));
698	            if (splitImages(materialNotifyTaskAutomation.getImages()).size() < 3) {
699	                log.warn("autoExecuteNotifyTasks skip node {} due to invalid images", node);
700	                continue;
701	            }
702	            String gbCode = order == null ? null : order.getGbCode();
703	            String departmentCode = resolveDepartmentCode(order);
704	            if (!notifyAutomationConfig.isAutoNotifyOpen(
705	                    node.getMaterialCode(), gbCode, node.getExecutorId(), departmentCode)) {
706	                continue;
707	            }
708	            DispatchHandleParam handleParam = new DispatchHandleParam();
709	            handleParam.setTaskDispatchNodeId(node.getTaskDispatchNodeId());
710	            handleParam.setRemarks("自动通知复尺");
711	            handleParam.setImages(splitImages(materialNotifyTaskAutomation.getImages()));
712	            handleParam.setNoticeRetainTime(materialNotifyTaskAutomation.getRecommendVisitTime());
713	            try {
714	                materialHandleV2Service.handleNode(handleParam, operatorDTO);
715	
716	                MaterialNotifyTaskAutomation update = MaterialNotifyTaskAutomation.builder()
717	                        .id(materialNotifyTaskAutomation.getId())
718	                        .notifyExecuteType(NotifyExecuteTypeEnum.AUTO_NOTIFY.getValue())
719	                        .aiAdoptionType((byte) 1)
720	                        .build();
721	
722	                materialNotifyTaskAutomationDao.updateById(update);
723	                executedNodes.add(NotifyTaskDetailVO.builder()
724	                        .projectOrderId(String.valueOf(node.getProjectOrderId()))
725	                        .taskDispatchNodeId(node.getTaskDispatchNodeId())
726	                        .materialCode(node.getMaterialCode())
727	                        .build());
728	                successCount++;
729	            } catch (Exception e) {
730	                logger.error("autoExecuteNotifyTasks handleNode error", e);
731	            }
732	        }
733	        logger.info("autoExecuteNotifyTasks executed={}/skipped={}/failed={}/total={}/date={}/executedNodes={}",
734	                successCount, 0, 0, candidates.size(), DateUtil.format(new Date(), DateUtil.DEFAULT_DATE_FORMAT), executedNodes);
735	
736	        return NotifyTaskAutoExecuteResultVO.builder()
737	                .candidateCount(candidates.size())
738	                .executedCount(successCount)
739	                .autoNotifyTaskDetailList(executedNodes)
740	                .build();
741	    }
