743	    private Integer classifyAdoption(MaterialNotifyTaskAutomation auto, Set<String> confirmedImages,
744	                                     Date confirmedTime) {
745	        if (auto == null || StringUtils.isEmpty(auto.getImages())) {
746	            return null;
747	        }
748	        Set<String> autoImages = new HashSet<>(splitImages(auto.getImages()));
749	        boolean imgSame = autoImages.equals(confirmedImages) && confirmedImages.containsAll(autoImages);
750	        boolean timeSame = auto.getRecommendVisitTime() != null && confirmedTime != null
751	                && auto.getRecommendVisitTime().getTime() == confirmedTime.getTime();
752	        if (imgSame && timeSame) {
753	            return AiAdoptionTypeEnum.ACCEPTED.getCode();
754	        }
755	        if (!imgSame && !timeSame) {
756	            return AiAdoptionTypeEnum.NOT_ACCEPTED.getCode();
757	        }
758	        return imgSame ? AiAdoptionTypeEnum.IMAGE_ACCEPTED.getCode() : AiAdoptionTypeEnum.VISIT_TIME_ACCEPTED.getCode();
759	    }
