946	    /**
947	     * 【测试】复尺提交调中控失败 → 给项目经理和设计师发 IM push（手动验证用后门）
948	     * <p>
949	     * {@code MaterialMeasureServiceImpl#pushResizeCommitFailMsg(Long, Throwable)} 是私有方法，
950	     * 平时只在「复尺提交时调中控（报价变更/自动下单）失败」的异步分支里被调用，正常流程很难复现。
951	     * 这里按 taskDispatchId 反射直接触发一次，并把解析出来的收件人/文案回显出来便于核验。
952	     * <p>
953	     * 注意：被调方法内部吞异常，所以返回 success 只代表「已触发」，实际是否收到 push 还要看客户端；
954	     * 回显里的 foremanId / designerId 为空则说明查不到收件人。
955	     *
956	     * @param taskDispatchId 复尺任务id
957	     */
958	    @ApiOperation("【测试】复尺调中控失败发IM push")
959	    @GetMapping("/backdoor/measure/pushResizeCommitFail")
960	    public ResultDTO<Map<String, Object>> pushResizeCommitFail(@RequestParam("taskDispatchId") Long taskDispatchId) {
961	        Preconditions.checkArgument(Objects.nonNull(taskDispatchId), "taskDispatchId 不能为空");
962	        Object measureService = ApplicationContextUtil.getApplicationContext().getBean(MaterialMeasureService.class);
963	        // 有可能是 CGLIB / JDK 动态代理，先拿到真正的目标对象再反射调用私有方法
964	        Object target = AopProxyUtils.getSingletonTarget(measureService);
965	        if (Objects.isNull(target)) {
966	            target = measureService;
967	        }
968	        try {
969	            Method method = AopUtils.getTargetClass(target)
970	                    .getDeclaredMethod("pushResizeCommitFailMsg", Long.class, Throwable.class);
971	            method.setAccessible(true);
972	            method.invoke(target, taskDispatchId, new RuntimeException("【测试】模拟变更下单失败"));
973	        } catch (InvocationTargetException e) {
974	            // 该方法约定自身不抛异常，真抛出来说明代码有问题
975	            logger.error("【测试】pushResizeCommitFailMsg 反射调用异常, taskDispatchId:{}", taskDispatchId, e.getTargetException());
976	            return new ResultDTO<>().fail("执行异常：" + e.getTargetException());
977	        } catch (Exception e) {
978	            logger.error("【测试】pushResizeCommitFailMsg 调用失败, taskDispatchId:{}", taskDispatchId, e);
979	            return new ResultDTO<>().fail("调用失败：" + e.getMessage());
980	        }
981	
982	        // 回显解析结果，便于核验「谁应该收到消息」
983	        Map<String, Object> result = new LinkedHashMap<>();
984	        result.put("taskDispatchId", taskDispatchId);
985	        TaskDispatch taskDispatch = taskDispatchDao.getById(taskDispatchId);
986	        if (Objects.isNull(taskDispatch)) {
987	            result.put("tip", "任务不存在，未发送任何消息");
988	            return new ResultDTO<>().success(result);
989	        }
990	        result.put("projectOrderId", taskDispatch.getProjectOrderId());
991	        result.put("materialName", taskDispatch.getMaterialName());
992	        result.put("taskType", taskDispatch.getTaskType());
993	        result.put("isRecheckScale", Objects.equals(taskDispatch.getTaskType(), TaskTypeEnum.RECHECK_SCALE.getValue()));
994	        result.put("channel", PushChannelEnum.RENWUTIXING.getCode());
995	        // 文案直接反射取实现里的方法，避免后门和线上文案两处维护
996	        result.put("title", invokeMeasurePrivate(target, "buildResizeCommitFailTitle",
997	                new Class<?>[] {TaskDispatch.class}, taskDispatch));
998	
999	        ProjectOrderDetailBO projectOrder = projectOrderManager.getProjectOrder(taskDispatch.getProjectOrderId());
1000	        if (Objects.isNull(projectOrder)) {
1001	            result.put("tip", "项目订单查不到：方法内部会 NPE 并被吞掉，实际不会发出任何消息");
1002	            return new ResultDTO<>().success(result);
1003	        }
1004	        result.put("foremanId", projectOrder.getForemanId());
1005	        result.put("designerId", projectOrder.getDesignerId());
1006	        result.put("content", invokeMeasurePrivate(target, "buildResizeCommitFailContent",
1007	                new Class<?>[] {ProjectOrderDetailBO.class, List.class}, projectOrder,
1008	                Lists.newArrayList("【测试】模拟变更返回的失败原因")));
1009	        // 跳转链接：PRD 要求「点击跳转至对应复尺任务的完成态快照」
1010	        Object startNode = invokeMeasurePrivate(target, "queryLatestStartNode", new Class<?>[] {Long.class},
1011	                taskDispatchId);
1012	        if (Objects.nonNull(startNode) && startNode instanceof TaskDispatchNode) {
1013	            result.put("url", invokeMeasurePrivate(target, "buildMeasureDetailUrl",
1014	                    new Class<?>[] {TaskDispatch.class, TaskDispatchNode.class}, taskDispatch, startNode));
1015	        } else {
1016	            result.put("url", null);
1017	            result.put("urlTip", "该复尺任务没有有效的 START 节点，线上跳转会是空");
1018	        }
1019	        result.put("tip", "已触发；foremanId / designerId 有值则对应角色应收到「任务提醒」push");
1020	        return new ResultDTO<>().success(result);
1021	    }
1022	
1023	    /**
1024	     * 反射调用 MaterialMeasureServiceImpl 的私有方法（后门自用）
1025	     */
1026	    private Object invokeMeasurePrivate(Object target, String methodName, Class<?>[] paramTypes, Object... args) {
1027	        try {
1028	            Method method = AopUtils.getTargetClass(target).getDeclaredMethod(methodName, paramTypes);
1029	            method.setAccessible(true);
1030	            return method.invoke(target, args);
1031	        } catch (Exception e) {
1032	            logger.error("【测试】反射调用 {} 失败", methodName, e);
1033	            return "反射调用失败：" + e.getMessage();
1034	        }
1035	    }
1036	
1037	}
