196	    @Override
197	    public void instanceBind(Long templateId, Long oldProductComboId, String oldMaterialCode, String oldSupplierCode) {
198	        // 获取新主材配置
199	        List<NMaterialTemplate> materialTemplateList = materialTemplateDao.queryList(NMaterialTemplateCondition.builder().templateCode(templateId + "")
200	                .state(com.ke.utopia.starlord.enumeration.StateEnum.VALID.getValue().byteValue()).build());
201	        Preconditions.checkArgument(!CollectionUtils.isEmpty(materialTemplateList), "没有查到新配置");
202	
203	        List<NMaterialTemplateForm> templateFormList = materialConfigV2Service
204	                .queryAllMaterialTemplateForm(NMaterialTemplateUnitCondition.builder().templateId(materialTemplateList.get(0).getId())
205	                        .state(com.ke.utopia.starlord.enumeration.StateEnum.VALID.getValue().byteValue()).build());
206	        Preconditions.checkArgument(!CollectionUtils.isEmpty(templateFormList), "没有查到新配置");
207	        Map<Integer, NMaterialProcessDefineForm> materialTaskMap = templateFormList.get(0).getProcessDefineList()
208	                .stream().collect(Collectors.toMap(NMaterialProcessDefineForm::getTaskType, Function.identity(),
209	                        (key1, key2) -> key2));
210	        // 查老配置
211	        List<MaterialTask> materialTaskList = oldMaterialTaskDao.listByCondition(
212	                QueryMaterialTaskCondition.builder().productComboId(oldProductComboId).materialCode(oldMaterialCode)
213	                        .supplierCode(oldSupplierCode).state(com.ke.utopia.starlord.enumeration.StateEnum.VALID.getValue()).build());
214	
215	        for (MaterialTask materialTask : materialTaskList) {
216	            NMaterialProcessDefineForm materialForm = materialTaskMap.get(materialTask.getTaskType());
217	
218	            List<MaterialTaskNode> nodeList = oldMaterialTaskNodeDao.queryList(QueryMaterialTaskNodeCondition.builder()
219	                    .taskId(materialTask.getId()).state(StateEnum.VALID.getValue()).build());
220	            List<String> nodeCodeList = nodeList.stream().map(MaterialTaskNode::getNodeType).sorted().distinct()
221	                    .map(nodeType -> CommonConstant.NODE_CODE_FACTOR * nodeType).map(String::valueOf).collect(Collectors.toList());
222	            nodeCodeList.add(0,CommonConstant.START_NODE_CODE);
223	            nodeCodeList.add(CommonConstant.FINISH_NODE_CODE);
224	            TaskDispatchExample example = new TaskDispatchExample();
225	            example.createCriteria().andTemplateIdEqualTo(materialTask.getId());
226	            TaskDispatch updateTask = TaskDispatch.builder().processCode(materialForm.getProcessCode())
227	                    .nodePath(Joiner.on(",").join(nodeCodeList)).build();
228	            taskDispatchDao.updateByExampleSelective(updateTask, example);
229	
230	
231	            for (MaterialTaskNode node : nodeList) {
232	                TaskDispatchNode updateNode = TaskDispatchNode.builder().processCode(materialForm.getProcessCode())
233	                        .nodeCode(node.getNodeType().intValue() * 1000).taskCode(node.getNodeType() * 1000 + "")
234	                        .uTaskCode(
235	                                CodeJointConvert.jointUtaskCode(materialForm.getProcessCode(), node.getNodeType() * 1000 + ""))
236	                        .build();
237	
238	                TaskDispatchNodeExample exampleNode = new TaskDispatchNodeExample();
239	                exampleNode.createCriteria().andTemplateNodeIdEqualTo(node.getId());
240	                taskDispatchNodeDao.updateByExampleSelective(updateNode, exampleNode);
241	            }
242	        }
243	    }
