407	    @Transactional(rollbackFor = Exception.class)
408	    public void copyConfig(String originProcessCode, String targetProcessCode) {
409	        // 查询 or 创建草稿态
410	        String templateCode = LangUtils.getTemplateCodeByProcessCode(targetProcessCode);
411	        materialTemplateV2Service.templateToEdit(TempateToEditParam.builder().templateCode(templateCode).build());
412	
413	        // target 配置查询
414	        NMaterialProcessDefine targetProcessDefine = nMaterialProcessDefineDao.queryList(NMaterialProcessDefineCondition
415	                .builder().stateList(Lists.newArrayList(TemplateStateEnum.SKETCH.getValue(),TemplateStateEnum.SKETCH_INIT.getValue())).processCode(targetProcessCode).build()).get(0);
416	        logger.info("复制配置copyConfig targetProcessDefine:{}", JSON.toJSONString(targetProcessDefine));
417	
418	        // copy
419	        List<NMaterialTimeCfg> originConfigs = nMaterialTimeCfgDao.queryList(NMaterialTimeCondition.builder()
420	                .processCode(originProcessCode).stateIn(Lists.newArrayList(TemplateStateEnum.ACTIVE.getByteValue(), TemplateStateEnum.INVALID.getByteValue()))
421	                .timeTypeEnums(REFUNDSUPPLE_STATUS_LIST).build());
422	        List<NMaterialTimeCfg> targetConfigs = nMaterialTimeCfgDao.queryList(NMaterialTimeCondition.builder()
423	                .processCode(targetProcessCode).state(TemplateStateEnum.SKETCH.getByteValue())
424	                .timeTypeEnums(REFUNDSUPPLE_STATUS_LIST).build());
425	
426	        if (org.apache.commons.collections4.CollectionUtils.isEmpty(originConfigs) || org.apache.commons.collections4.CollectionUtils.isNotEmpty(targetConfigs)) {
427	            logger.info("复制配置copyConfig 无需插入 originConfigs：{} targetConfigs：{}", originConfigs, targetConfigs);
428	            return;
429	        }
430	        logger.info("复制配置copyConfig 查询到origin-time配置：{}", JSON.toJSONString(originConfigs));
431	
432	        // 查timeRelation
433	        Multimap<Long, NMaterialTimeRelation> relationMap;
434	        List<Long> timeIds = originConfigs.stream().map(NMaterialTimeCfg::getId).collect(Collectors.toList());
435	        if (!org.apache.commons.collections4.CollectionUtils.isEmpty(timeIds)) {
436	            relationMap = nMaterialTimeRelationDao
437	                    .queryMap(NMaterialTimeRelationCondition.builder().timeIds(timeIds).build());
438	            logger.info("复制配置copyConfig 查询到origin-relation配置：{}", JSON.toJSONString(relationMap.values()));
439	        } else {
440	            throw new UtopiaBussinessException(ResultCodeEnum.ERROR_NO_DATA, "未查询到对应的relation");
441	        }
442	
443	        // insert
444	        originConfigs.forEach(origin -> {
445	
446	            NMaterialTimeCfg newCfg = new NMaterialTimeCfg();
447	            BeanUtils.copyProperties(origin, newCfg);
448	            newCfg.setId(null);
449	            newCfg.setUTaskCode(targetProcessCode + "_" + newCfg.getTaskCode());
450	            newCfg.setProcessCode(targetProcessCode);
451	            newCfg.setVersion(targetProcessDefine.getVersion());
452	            newCfg.setCreateTime(new Date());
453	            newCfg.setUpdateTime(new Date());
454	            newCfg.setState(targetProcessDefine.getState());
455	            int insertCount = nMaterialTimeCfgDao.insert(newCfg);
456	            logger.info("复制配置copyConfig 插入n_material_time_cfg：{},【插入是否成功】：{}", JSON.toJSONString(newCfg), insertCount > 0);
457	
458	            List<NMaterialTimeRelation> originTimeRelations = new ArrayList<>(relationMap.get(origin.getId()));
459	            for (NMaterialTimeRelation originRelation : originTimeRelations) {
460	                NMaterialTimeRelation targetRelation = new NMaterialTimeRelation();
461	                BeanUtils.copyProperties(originRelation, targetRelation);
462	                targetRelation.setId(null);
463	                targetRelation.setTimeId(newCfg.getId());
464	                targetRelation.setProcessCode(targetProcessCode);
465	                targetRelation.setVersion(targetProcessDefine.getVersion());
466	                targetRelation.setUTaskCode(targetProcessCode + "_" + originRelation.getTaskCode());
467	                targetRelation.setCreateTime(new Date());
468	                targetRelation.setUpdateTime(new Date());
469	                targetRelation.setState(targetProcessDefine.getState());
470	                int insertRelation = nMaterialTimeRelationDao.insert(targetRelation);
471	                logger.info("复制配置copyConfig 插入n_material_time_relation：{},【插入是否成功】：{}", JSON.toJSONString(targetRelation),
472	                        insertRelation > 0);
473	            }
474	
475	        });
476	        // 生效配置
477	        TemplatePublishParam templatePublishParam = new TemplatePublishParam();
478	        templatePublishParam.setTemplateId(targetProcessDefine.getTemplateId());
479	        materialConfigV2Service.activeTemplate(templatePublishParam);
480	
481	    }
