317	    @PostMapping("/backdoor/sinvoke")
318	    @ResponseBody
319	    public ResultDTO sinvoke(String serviceName, String methodName,
320	            @RequestParam(value = "params", required = false) List<String> params)
321	            throws InvocationTargetException, IllegalAccessException {
322	        Object bean = ApplicationContextUtil.getApplicationContext().getBean(serviceName);
323	        Class<?> clazz = bean.getClass();
324	        Method[] methods = clazz.getMethods();
325	
326	        for (Method method : methods) {
327	            // 不支持重载方法
328	            if (method.getName().equals(methodName)) {
329	                if (params == null) {
330	                    Object result = method.invoke(bean);
331	                    return new ResultDTO<>().success(result);
332	                }
333	                Class<?>[] parameterTypes = method.getParameterTypes();
334	                Object[] paramObjects = new Object[params.size()];
335	                for (int index = 0; index < params.size(); index++) {
336	                    Object object = null;
337	
338	                    Class<?> type = parameterTypes[index];
339	                    if (type == Integer.class) {
340	                        object = new Integer(params.get(index));
341	                    } else if (type == String.class) {
342	                        if (params.get(index).equals("null")) {
343	                            object = null;
344	                        } else {
345	                            object = params.get(index);
346	                        }
347	                    } else if (type == Long.class) {
348	                        object = new Long(params.get(index));
349	                    } else if (type == Date.class) {
350	                        object = DateUtil.parse(params.get(index), "yyyy-MM-dd HH:mm:ss");
351	                    } else if (params.get(index).startsWith("{") || type == List.class) {
352	                        object = JsonUtils.readJsonToBean(params.get(index), parameterTypes[index]);
353	                    }
354	
355	                    // if(type == List.class){
356	                    // Type genericType = type.getGenericInterfaces();
357	                    // object = JsonUtils.readJsonToBean(params.get(index), new TypeReference<type>() {
358	                    // });
359	                    // }
360	                    paramObjects[index] = object;
361	                }
362	                Object result = method.invoke(bean, paramObjects);
363	                return new ResultDTO<>().success(result);
364	            }
365	        }
366	        return new ResultDTO<>().fail("没有这个方法");
367	    }
