29	
30	@Component
31	@Slf4j
32	@WebFilter(filterName = "StarLordToolFilter", urlPatterns = "/*")
33	public class StarLordToolFilter implements Filter {
34	
35	    private PathMatcher pathMatcher = new AntPathMatcher();
36	
37	    @Value("${starlord.tool.admin.user:0}")
38	    private List<Long> adminUserList;
39	
40	    @Value("${starlord.tool.supervisor.user:0}")
41	    private List<Long> supervisorUserList;
42	
43	    @Value("${starlord.tool.supervisor.resource:0}")
44	    private List<String> supervisorResourceList;
45	
46	    @Resource
47	    private OperationLogDao operationLogDao;
48	
49	
50	    @Override
51	    public void doFilter(ServletRequest request, ServletResponse response, FilterChain chain) throws IOException, ServletException {
52	        ContentCachingRequestWrapper wrappedRequest = new ContentCachingRequestWrapper((HttpServletRequest) request);
53	        ContentCachingResponseWrapper wrappedResponse = new ContentCachingResponseWrapper((HttpServletResponse) response);
54	
55	        if (!ArrayUtils.isEmpty(wrappedRequest.getCookies())){
56	            String hetuToken = Arrays.stream(wrappedRequest.getCookies()).filter(p -> p.getName().equals("paris_hetu_token")).map(p->p.getValue()).findFirst().orElse(null);
57	            if (StringUtils.isNotBlank(hetuToken)){
58	                String _ucId = wrappedRequest.getHeader("ucId");
59	                Long ucId = Long.valueOf(_ucId);
60	                if (!adminUserList.contains(0L) && !adminUserList.contains(ucId) && !supervisorUserList.contains(ucId)){
61	                    throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PERMISSION_DENIED,"没有权限访问");
62	                }
63	
64	                if (supervisorResourceList.stream().anyMatch(s->pathMatcher.match(s, wrappedRequest.getRequestURI())) &&
65	                        !supervisorUserList.contains(ucId)){
66	                    throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PERMISSION_DENIED,"没有权限访问");
67	                }
68	                Exception ex = null;
69	                try {
70	                    chain.doFilter(wrappedRequest,wrappedResponse);
71	                    wrappedResponse.copyBodyToResponse();
72	                }catch (Exception e){
73	                    ex = e;
74	                    throw e;
75	                }finally {
76	                    saveLog(wrappedRequest,wrappedResponse,ex);
77	                }
78	                return;
79	            }
80	        }
81	
82	        chain.doFilter(wrappedRequest,wrappedResponse);
83	        wrappedResponse.copyBodyToResponse();
84	
85	    }
86	
87	
88	    public void saveLog(ContentCachingRequestWrapper request, ContentCachingResponseWrapper response,Exception ex) {
89	        try {
90	            if (supervisorResourceList.stream().noneMatch(s->pathMatcher.match(s, request.getRequestURI()))){
91	                return;
92	            }
93	            // 记录日志
94	            String _ucId = request.getHeader("ucId");
95	            OperationLog operationLog = new OperationLog();
96	            operationLog.setUserId(Long.valueOf(_ucId));
97	            operationLog.setType(1);
98	            operationLog.setTraceId(HttpLogContext.getTraceId());
99	            operationLog.setResource(request.getRequestURI());
100	            String body = new String(request.getContentAsByteArray());
101	            Map<String, Object> requestParam = ImmutableMap.of("parameter", request.getParameterMap(), "body", body);
102	            operationLog.setRequest(JsonUtils.writeObjectAsJson(requestParam));
103	            String responseBody = new String(response.getContentAsByteArray());
104	            String exception = Objects.isNull(ex) ? "" : ExceptionUtils.getStackTrace(ex);
105	            Map<String, Object> responseParam = ImmutableMap.of("exception", exception, "body",responseBody);
106	            operationLog.setResponse(JsonUtils.writeObjectAsJson(responseParam));
107	            operationLog.setLocalIp(AddressUtil.getIp());
108	            operationLog.setRemoteIp(request.getRemoteHost());
109	            operationLog.setCtime(new Date());
110	            operationLog.setMtime(new Date());
111	            operationLogDao.insertSelective(operationLog);
112	        }catch (Exception e){
113	            log.error("",e);
114	        }
115	
116	    }
117	}
